with e as(select * from jsonb_array_elements('[{"relation":"works","id":987111004,"after":{"id":987111004,"title":"Candide","cover_id":null,"author_id":987311002,"work_type":null,"source_type":"open_library","open_library_id":"OL100672W","first_publish_year":1759,"native_identity_key":"nlscale:fixture012:334"}},{"relation":"editions","id":987211007,"work_id":987111004,"language":"dut","after":{"id":987211007,"title":"Candide, of Het optimisme","isbn_10":null,"isbn_13":"9789029554343","work_id":987111004,"cover_id":null,"language":"dut","publisher":"De Arbeiderpers","publish_date":null,"open_library_edition_id":"OL24328781M"}},{"relation":"catalog_work_descriptions","work_id":987111004,"language":"nl","after":{"text":"Candide groeit op met de overtuiging dat alles uiteindelijk zo goed mogelijk geregeld is. Wanneer zijn liefde voor de dochter van een baron wordt ontdekt, moet hij de beschermde omgeving verlaten. Tijdens reizen door verschillende werelddelen krijgt hij vervolgens met geweld, rampen en willekeur te maken. Zijn ervaringen botsen steeds opnieuw met de geruststellende lessen van zijn leermeester Pangloss. Voltaire gebruikt die tegenstelling om vastgeroeste zekerheden en het gemak van theoretisch optimisme te bevragen.","work_id":987111004,"evidence":[{"note":"Candide ou L’optimisme1759, exact Dutch hardcover. KB explicitly explains shortened front title Candide. BnF contemporary1759edition and historical chronology corroborate1759; current1746does not belong to Candide. Canonical original Work is unchanged.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p03620532X"],"reference":"work:334","checked_at":"2026-11-02T19:50:00.000Z","supplemental":null},{"type":"original_substantive_source_review","review":"content-review-016.json","sources":["https://candide.bnf.fr/reperes","https://ccfr.bnf.fr/portailccfr/ark%3A/16871/0013053104","https://openlibrary.org/works/OL100672W","https://data.bibliotheken.nl/id/nbt/p036205